"""Independently check the large-publication exports generated by the benchmark."""
import argparse
from pathlib import Path

from pypdf import PdfReader


def check_publication(path, expected_pages, text_samples, has_images):
    reader = PdfReader(path, strict=True)
    assert len(reader.pages) == expected_pages, path
    for page in reader.pages:
        assert '/TrimBox' in page and '/BleedBox' in page, path
        assert page.mediabox == page.trimbox, path
        operations = page.get_contents().operations
        assert operations, path
        if has_images:
            assert sum(operator == b'Do' for _, operator in operations) == 3, path
    for positions, text in text_samples:
        assert any(text in ' '.join(reader.pages[position].extract_text().split())
                   for position in positions), (path, positions, text)


def render_sample(path, position):
    import pypdfium2
    reader = pypdfium2.PdfDocument(path)
    try:
        page = reader[position]
        try:
            bitmap = page.render(scale=1)
            try:
                image = bitmap.to_pil().convert('RGB')
                assert image.getextrema() != ((255, 255), (255, 255), (255, 255)), path
                image.save(path.with_name(path.stem + '-sample.png'))
            finally:
                bitmap.close()
        finally:
            page.close()
    finally:
        reader.close()


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--render', action='store_true', help='Render representative pages with PDFium.')
    args = parser.parse_args()
    folder = Path('build/production-benchmark')
    book, magazine = folder / 'book.pdf', folder / 'magazine.pdf'
    check_publication(book, 250, [((0,), 'Entry 1.'), ((225,), 'Entry 1.'), (range(249, 224, -1), 'Entry 300.')], False)
    check_publication(magazine, 40, [((0,), 'Field journal · 1'), ((39,), 'Field journal · 40')], True)
    if args.render:
        render_sample(book, 225)
        render_sample(magazine, 39)
    print('Validated 250 book pages and 40 illustrated magazine pages.')
